"""REFERENCE: an accepted Codeforces submission: compiles the C++ below with g++ -O2 (once, cached next to this file) and runs it on stdin."""
import hashlib
import os
import subprocess
import sys

SRC = "#include <bits/stdc++.h>\nusing namespace std;\ntemplate <typename T>\nvoid rd(T& x) {\n  int f = 0, c;\n  while (!isdigit(c = getchar())) f ^= !(c ^ 45);\n  x = (c & 15);\n  while (isdigit(c = getchar())) x = x * 10 + (c & 15);\n  if (f) x = -x;\n}\ntemplate <typename T>\nvoid pt(T x, int c = -1) {\n  if (x < 0) putchar('-'), x = -x;\n  if (x > 9) pt(x / 10);\n  putchar(x % 10 + 48);\n  if (c != -1) putchar(c);\n}\nconst int P = 998244353;\nint ad(int k1, int k2) { return k1 += k2 - P, k1 += k1 >> 31 & P; }\nint su(int k1, int k2) { return k1 -= k2, k1 += k1 >> 31 & P; }\nint mu(int k1, int k2) { return 1LL * k1 * k2 % P; }\nvoid uad(int& k1, int k2) { k1 += k2 - P, k1 += k1 >> 31 & P; }\nvoid usu(int& k1, int k2) { k1 -= k2, k1 += k1 >> 31 & P; }\ntemplate <typename... T>\nint ad(int k1, T... k2) {\n  return ad(k1, ad(k2...));\n}\ntemplate <typename... T>\nvoid uad(int& k1, T... k2) {\n  return uad(k1, ad(k2...));\n}\ntemplate <typename... T>\nvoid usu(int& k1, T... k2) {\n  return usu(k1, ad(k2...));\n}\ntemplate <typename... T>\nint mu(int k1, T... k2) {\n  return mu(k1, mu(k2...));\n}\nint po(int k1, int k2) {\n  int k3 = 1;\n  for (; k2; k2 >>= 1, k1 = mu(k1, k1))\n    if (k2 & 1) k3 = mu(k3, k1);\n  return k3;\n}\nnamespace ntt {\nint base = 1, root = -1, maxbase = -1;\nstd::vector<int> roots = {0, 1}, rev = {0, 1};\nvoid init() {\n  int tmp = P - 1;\n  maxbase = 0;\n  while (!(tmp & 1)) tmp >>= 1, maxbase++;\n  root = 2;\n  while (1) {\n    if (po(root, 1 << maxbase) == 1 && po(root, 1 << (maxbase - 1)) != 1) break;\n    root++;\n  }\n}\nvoid ensure_base(int nbase) {\n  if (maxbase == -1) init();\n  if (nbase <= base) return;\n  rev.resize(1 << nbase);\n  for (int i = 1; i < (1 << nbase); ++i)\n    rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << (nbase - 1));\n  roots.resize(1 << nbase);\n  while (base < nbase) {\n    int z = po(root, 1 << (maxbase - base - 1));\n    for (int i = (1 << (base - 1)); i < (1 << base); ++i)\n      roots[i << 1] = roots[i], roots[i << 1 | 1] = mu(roots[i], z);\n    base++;\n  }\n}\nvoid dft(std::vector<int>& a) {\n  int n = a.size(), zeros = __builtin_ctz(n);\n  ensure_base(zeros);\n  int shift = base - zeros;\n  for (int i = 0; i < n; ++i)\n    if (i < (rev[i] >> shift)) std::swap(a[i], a[rev[i] >> shift]);\n  for (int mid = 1; mid < n; mid <<= 1)\n    for (int i = 0; i < n; i += (mid << 1))\n      for (int j = 0; j < mid; ++j) {\n        int x = a[i + j], y = mu(a[i + j + mid], roots[mid + j]);\n        a[i + j] = ad(x, y);\n        a[i + j + mid] = su(x, y);\n      }\n}\nstd::vector<int> operator*(std::vector<int> a, std::vector<int> b) {\n  if (((int)(a).size()) <= 50 && ((int)(b).size()) <= 50) {\n    vector<int> c(((int)(a).size()) + ((int)(b).size()) - 1);\n    for (int i = (0); i <= (((int)(a).size()) - 1); ++i)\n      for (int j = (0); j <= (((int)(b).size()) - 1); ++j)\n        uad(c[i + j], mu(a[i], b[j]));\n    return c;\n  }\n  int need = a.size() + b.size() - 1, nbase = 0;\n  while ((1 << nbase) < need) nbase++;\n  ensure_base(nbase);\n  int size = 1 << nbase;\n  a.resize(size);\n  b.resize(size);\n  dft(a);\n  dft(b);\n  int inv = po(size, P - 2);\n  for (int i = 0; i < size; ++i) a[i] = mu(a[i], mu(b[i], inv));\n  std::reverse(a.begin() + 1, a.end());\n  dft(a);\n  a.resize(need);\n  return a;\n}\n}  // namespace ntt\nusing ntt::operator*;\nvector<int> operator+(vector<int> a, vector<int> b) {\n  if (a.size() < b.size()) a.resize(b.size());\n  for (int i = 0; i < (int)b.size(); i++) uad(a[i], b[i]);\n  return a;\n}\nconst int N = 1e5 + 5;\nvector<int> poly[N];\nint a[N], b[N], fac[N], inv[N];\nint n, m, tot;\nvector<int> solve(int l, int r) {\n  if (l == r) return poly[l];\n  int mid = (l + r) >> 1;\n  return solve(l, mid) * solve(mid + 1, r);\n}\nvector<int> f[N][2][2];\nint vis[N][2][2];\nvector<int> calc(int len, int l, int r) {\n  if (len == 0) {\n    vector<int> ans(1);\n    ans[0] = 1;\n    return ans;\n  }\n  if (len == 1) {\n    vector<int> ans(2);\n    ans[0] = 1;\n    ans[1] = mu((P + 1) / 2, po(2, 2 - l - r));\n    return ans;\n  }\n  if (len == 2) {\n    vector<int> ans(3);\n    ans[0] = 1;\n    ans[1] = 4 - l - r;\n    ans[2] = mu((P + 1) / 2, po(2, 2 - l - r));\n    return ans;\n  }\n  if (vis[len][l][r]) return f[len][l][r];\n  vis[len][l][r] = 1;\n  for (int i = 0; i <= 1; i++) {\n    vector<int> L = calc((len - 1) >> 1, l, i);\n    vector<int> R = calc(len >> 1, i, r);\n    L = L * R;\n    if (i == 1) {\n      L.push_back(0);\n      for (int i = (int)L.size() - 1; i >= 1; i--) L[i] = mu(L[i - 1], 2);\n      L[0] = 0;\n    }\n    f[len][l][r] = f[len][l][r] + L;\n  }\n  return f[len][l][r];\n}\nint main() {\n  fac[0] = 1;\n  for (int i = 1; i <= 100000; i++) fac[i] = mu(fac[i - 1], i);\n  inv[100000] = po(fac[100000], P - 2);\n  for (int i = 100000; i >= 1; i--) inv[i - 1] = mu(inv[i], i);\n  rd(n);\n  for (int i = 1; i <= n; i++) rd(a[i]);\n  for (int l = 1, r; l <= n; l = r + 1) {\n    int len = a[l];\n    r = l + len - 1;\n    if (r > n) {\n      pt(0, '\\n');\n      return 0;\n    }\n    for (int i = l; i <= r; i++) {\n      if (a[i] != len) {\n        pt(0, '\\n');\n        return 0;\n      }\n    }\n    b[++m] = len;\n  }\n  for (int l = 1, r; l <= m; l = r + 1) {\n    r = l;\n    if (b[l] != 1) continue;\n    while (r < m && b[r + 1] == 1) ++r;\n    poly[++tot] = calc(r - l + (l != 1) + (r != m), l != 1, r != m);\n  }\n  for (int i = 1; i < m; i++) {\n    if (b[i] != 1 && b[i + 1] != 1) {\n      ++tot;\n      poly[tot].resize(2);\n      poly[tot][0] = 1;\n      poly[tot][1] = (P + 1) / 2;\n    }\n  }\n  int coef = 1;\n  for (int i = 1; i <= m; i++) {\n    if (b[i] != 1) {\n      coef = mu(coef, 2);\n    }\n  }\n  vector<int> res(1, 1);\n  if (tot) res = solve(1, tot);\n  int ans = 0;\n  for (int i = 0; i < m; i++) {\n    int now = mu(res[i], fac[m - i]);\n    if (i & 1)\n      ans = su(ans, now);\n    else\n      ans = ad(ans, now);\n  }\n  pt(mu(ans, coef), '\\n');\n  return 0;\n}\n"

here = os.path.dirname(os.path.abspath(__file__))
exe = os.path.join(here, ".build-" + hashlib.sha1(SRC.encode()).hexdigest()[:12])
if not os.path.exists(exe):
    with open(exe + ".cpp", "w") as f:
        f.write(SRC)
    subprocess.run(["g++", "-O2", "-std=gnu++17", "-o", exe, exe + ".cpp"], check=True)
sys.exit(subprocess.run([exe]).returncode)
